insert into public.store_settings (id, store_name, support_email, support_phone, announcement, pickup_address, pickup_hours) values (1, 'Perferm', 'concierge@perferm.ng', '+234 801 234 5678', 'Delivery to all 36 states + FCT', '12 Admiralty Way, Lekki Phase 1, Lagos', 'Mon – Sat, 10:00 – 19:00') on conflict (id) do nothing;
insert into public.collections (slug, title, accent, eyebrow, description, image_src, image_alt, position) values
  ('arabian', 'Arabian perfumery', 'Arabian', 'The heritage', 'Saffron, Taif rose, amber and resin — the grand tradition of the Gulf''s perfume houses, composed for skin that lives in the Lagos heat.', 'https://images.pexels.com/photos/34051691/pexels-photo-34051691.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Three ornate Arabian perfume bottles resting on white linen', 0),
  ('oud', 'The oud edit', 'oud', 'Liquid gold', 'Aged agarwood from Cambodia, Assam and Hindi oud, from smoky bakhoor to the most refined extraits. Deep, resinous, unforgettable.', 'https://images.pexels.com/photos/30981935/pexels-photo-30981935.jpeg?auto=compress&cs=tinysrgb&w=2000', 'A dark perfume bottle on a carved agarwood base in warm light', 1),
  ('niche', 'Niche houses', 'niche', 'Rare & independent', 'Small-batch perfumery from independent ateliers in Paris and Grasse — signatures you will not smell on anyone else in the room.', 'https://images.pexels.com/photos/35930230/pexels-photo-35930230.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Niche perfume bottles lined up on a reflective black surface', 2),
  ('attars', 'Attar oils', 'attars', 'Concentrated', 'Alcohol-free perfume oils, hand-poured in crystal flacons. A single drop on the pulse lasts from morning majlis to midnight.', 'https://images.pexels.com/photos/17155311/pexels-photo-17155311.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Crystal attar oil bottles arranged on a wooden shelf', 3),
  ('gift-sets', 'Gift sets', 'gifting', 'To be given', 'Coffrets and discovery wardrobes, wrapped by hand in our signature box — for weddings, Eid, birthdays and every reason in between.', 'https://images.pexels.com/photos/34144825/pexels-photo-34144825.jpeg?auto=compress&cs=tinysrgb&w=1600', 'A luxury perfume gift box resting on folds of silk', 4)
insert into public.products (slug, name, house, tagline, description, gender, concentration, families, notes_top, notes_heart, notes_base, longevity, sillage, is_new, is_bestseller, created_at) values ('oud-al-layl', 'Oud Al Layl', 'Maison Saffah', 'Smoked oud, Taif rose & ambergris', 'A nocturne in oud. Cambodian agarwood is lit with saffron and bergamot, softened by a heart of Taif rose and laid to rest on ambergris and supple leather. Composed for long evenings — it opens bold, and dries down to a warm, resinous glow that clings to fabric for days.', 'unisex', 'extrait', array['woody', 'oriental']::public.scent_family[], array['Saffron', 'Bergamot']::text[], array['Cambodian oud', 'Taif rose']::text[], array['Ambergris', 'Leather', 'Agarwood smoke']::text[], '12+ hours', 'Enormous', false, true, '2026-03-14T09:00:00Z') on conflict (slug) do nothing;
insert into public.product_images (product_id, src, alt, position) select (select id from public.products where slug = 'oud-al-layl'), 'https://images.pexels.com/photos/7702669/pexels-photo-7702669.jpeg?auto=compress&cs=tinysrgb&w=1400', 'Oud Al Layl — black and gold flacon on a dark backdrop', 0 where not exists (select 1 from public.product_images where product_id = (select id from public.products where slug = 'oud-al-layl') and position = 0);
insert into public.product_images (product_id, src, alt, position) select (select id from public.products where slug = 'oud-al-layl'), 'https://images.pexels.com/photos/30981935/pexels-photo-30981935.jpeg?auto=compress&cs=tinysrgb&w=2000', 'Oud Al Layl resting on a carved agarwood base', 1 where not exists (select 1 from public.product_images where product_id = (select id from public.products where slug = 'oud-al-layl') and position = 1);
