insert into public.reviews (product_id, author_name, city, rating, title, body, status, verified_purchase, created_at) select (select id from public.products where slug = 'oud-al-layl'), 'Ibrahim K.', 'Victoria Island, Lagos', 5, 'The concierge helped me choose', 'I sent a voice note describing my wife''s taste and they recommended the Layali Gold. She hasn''t worn anything else since.', 'approved', true, '2026-07-30T12:00:00Z' where not exists (select 1 from public.reviews where product_id = (select id from public.products where slug = 'oud-al-layl') and author_name = 'Ibrahim K.');
insert into public.reviews (product_id, author_name, city, rating, title, body, status, verified_purchase, created_at) select (select id from public.products where slug = 'oud-al-layl'), 'Funmi A.', 'Ibadan', 5, 'Better than duty free', 'Prices are honest, the bottles are authentic and the discovery set let me try before committing to a full bottle.', 'approved', true, '2026-07-11T12:00:00Z' where not exists (select 1 from public.reviews where product_id = (select id from public.products where slug = 'oud-al-layl') and author_name = 'Funmi A.');
