insert into public.products (slug, name, house, tagline, description, gender, concentration, families, notes_top, notes_heart, notes_base, longevity, sillage, is_new, is_bestseller, created_at) values ('rose-de-taif', 'Rose de Taif', 'Dar Zahra', 'Taif rose, lychee & white musk', 'Harvested at dawn in the mountains above Taif, the rose here is dewy and luminous rather than heavy. Pink pepper and lychee give it a modern sparkle; sandalwood and white musk keep it close and elegant — a rose for the office, the brunch and the evening that follows.', 'her', 'edp', array['floral', 'oriental']::public.scent_family[], array['Pink pepper', 'Lychee']::text[], array['Taif rose', 'Peony']::text[], array['White musk', 'Sandalwood']::text[], '8–10 hours', 'Moderate', false, true, '2026-02-02T09:00:00Z') on conflict (slug) do nothing;
